def _require_valid_token(auth_token):
    """Raise ``PermissionError`` unless *auth_token* is valid."""
    if is_valid_token(auth_token):
        return

    raise PermissionError("invalid auth token")


def handle_request(data, auth_token):
    """Authenticate and process an incoming API request."""
    _require_valid_token(auth_token)
    return process(data)

